309	    int ret = tls_write_all(ctx, (const unsigned char*)req, (size_t)n);
310	
311	    if (ret != 0) {
312	        return ret;
313	    }
314	
315	    char resp[1024];
316	    size_t rlen = 0;
317	
318	    while (rlen < sizeof(resp) - 1) {
319	        int r = mbedtls_ssl_read(&ctx->ssl, (unsigned char*)resp + rlen,
320	            sizeof(resp) - 1 - rlen);
321	
322	        if (r > 0) {
323	            rlen += (size_t)r;
324	            resp[rlen] = '\0';
325	            if (strstr(resp, "\r\n\r\n")) {
326	                break;
327	            }
328	        } else if (r == 0 || r == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
329	            return -ECONNRESET;
330	        } else if (r != MBEDTLS_ERR_SSL_WANT_READ) {
331	            return -EIO;
