333	    }
334	
335	    int status = 0;
336	
337	    if (sscanf(resp, "HTTP/1.1 %d", &status) != 1 || status != 101) {
338	        syslog(LOG_ERR, "[%s] WS upgrade failed: HTTP %d\n", TAG, status);
339	        return -EPROTO;
340	    }
