233	static int tls_write_all(tts_tls_ctx_t* ctx, const unsigned char* buf,
234	    size_t len)
235	{
236	    size_t written = 0;
237	
238	    while (written < len) {
239	        int ret = mbedtls_ssl_write(&ctx->ssl, buf + written, len - written);
240	
241	        if (ret > 0) {
242	            written += (size_t)ret;
243	        } else if (ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
244	            return -EIO;
245	        }
246	    }
247	
