251	static int tls_read_all(tts_tls_ctx_t* ctx, unsigned char* buf, size_t len)
252	{
253	    size_t got = 0;
254	
255	    while (got < len) {
256	        int ret = mbedtls_ssl_read(&ctx->ssl, buf + got, len - got);
257	
258	        if (ret > 0) {
259	            got += (size_t)ret;
260	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
261	            return -ECONNRESET;
262	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
263	            /* Distinguish SO_RCVTIMEO timeout from real I/O errors.
264	             * When the socket recv timeout fires, recv() returns -1
265	             * with errno EAGAIN/EWOULDBLOCK, and mbedtls maps that
266	             * to MBEDTLS_ERR_NET_RECV_FAILED (-0x004C).  Return a
267	             * distinct code so callers can treat timeout as normal
268	             * end-of-stream without masking real connection failures. */
269	            if (ret == -0x004C && (errno == EAGAIN || errno == EWOULDBLOCK
270	                                   || errno == ETIMEDOUT)) {
271	                return -ETIMEDOUT;
272	            }
273	            return -EIO;
274	        }
275	    }
276	
277	    return 0;
