/*
 * Doubao TTS via WebSocket — bidirectional streaming (V3 protocol).
 *
 * Protocol: wss://openspeech.bytedance.com/api/v3/tts/bidirection
 * (2026-08-14 改造：原 V1 ws_binary + Bearer ***REDACTED*** 403 根因 = 旧版控制台
 *  鉴权与资源未开通；新版双向流式用 X-Api-Key + X-Api-Resource-Id 鉴权，
 *  事件驱动：StartConnection → StartSession(req_params) → TaskRequest(text)
 *  → 收 TTSResponse 音频帧 → FinishSession → FinishConnection。)
 *
 * Binary frame format (same 4-byte header family as volc_asr):
 *   byte0: [version(4b) | header_size(4b)]   = 0x11 (v1, 4B header)
 *   byte1: [msg_type(4b) | flags(4b)]
 *   byte2: [serialization(4b) | compression(4b)] = 0x10 (JSON, none)
 *   byte3: 0x00 (padding to 4B header)
 *   Client send (marshal order):  event(i32 BE) [+ session_id(u32 len+utf8)]
 *                                 [+ sequence(i32 BE)] [payload u32 len + data]
 *   Server resp (unmarshal order): sequence(i32 BE, if Positive/NegativeSeq)
 *                                 + event(i32 BE) [+ session_id] [+ connect_id]
 *                                 [payload u32 len + data]
 *   flags: 0=NoSeq, 1=PositiveSeq, 2=LastNoSeq, 3=NegativeSeq, 4=WithEvent
 */

#include "infra/config_store.h"
#include "infra/http_proxy.h"
#include "agent_compat.h"
#include "agent_config.h"
#include "voice/volc_tts.h"

#include "cJSON.h"
#include "mbedtls/base64.h"
#include "mbedtls/ctr_drbg.h"
#include "mbedtls/net_sockets.h"
#include "mbedtls/ssl.h"

#include <errno.h>
#include <fcntl.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <time.h>

static const char* TAG = "volc_tts_ws";

#define TTS_WS_PATH "/api/v3/tts/bidirection"

/* Volcengine binary protocol constants (V3 bidirectional) */
#define VOLC_PROTO_VER 0x11
#define VOLC_HDR_SIZE 4 /* 4-byte protocol header */

/* MsgType (byte1 high nibble) */
#define VOLC_MSG_FULL_REQ 0x1   /* FullClientRequest */
#define VOLC_MSG_AUDIO_REQ 0x2  /* AudioOnlyClient */
#define VOLC_MSG_FULL_RESP 0x9  /* FullServerResponse */
#define VOLC_MSG_AUDIO_RESP 0xB /* AudioOnlyServer */
#define VOLC_MSG_FRONTEND 0xC   /* FrontEndResultServer */
#define VOLC_MSG_ERROR 0xF

/* Flags (byte1 low nibble) */
#define VOLC_FLAG_NOSEQ 0x0
#define VOLC_FLAG_POS_SEQ 0x1
#define VOLC_FLAG_LAST_NOSEQ 0x2
#define VOLC_FLAG_NEG_SEQ 0x3
#define VOLC_FLAG_WITH_EVENT 0x4

/* EventType (V3 bidirectional) */
#define VOLC_EVT_START_CONNECTION 1
#define VOLC_EVT_FINISH_CONNECTION 2
#define VOLC_EVT_CONNECTION_STARTED 50
#define VOLC_EVT_CONNECTION_FAILED 51
#define VOLC_EVT_CONNECTION_FINISHED 52
#define VOLC_EVT_START_SESSION 100
#define VOLC_EVT_CANCEL_SESSION 101
#define VOLC_EVT_FINISH_SESSION 102
#define VOLC_EVT_SESSION_STARTED 150
#define VOLC_EVT_SESSION_CANCELED 151
#define VOLC_EVT_SESSION_FINISHED 152
#define VOLC_EVT_SESSION_FAILED 153
#define VOLC_EVT_TASK_REQUEST 200
#define VOLC_EVT_UPDATE_CONFIG 201
#define VOLC_EVT_TTS_SENTENCE_START 350
#define VOLC_EVT_TTS_SENTENCE_END 351
#define VOLC_EVT_TTS_RESPONSE 352
#define VOLC_EVT_TTS_SUBTITLE 364
#define VOLC_EVT_TTS_ENDED 359

#define VOLC_SER_JSON 0x1

/* WebSocket constants */
#define WS_BUF_SIZE (32 * 1024)
#define WS_MASK_KEY_LEN 4
#define WS_OPCODE_BINARY 0x02
#define WS_OPCODE_CLOSE 0x08
#define WS_FIN_BIT 0x80
#define WS_MASK_BIT 0x80

/* Credentials */
static char s_api_key[128];
static char s_resource_id[64];
static char s_speaker[64];

typedef struct {
    mbedtls_ssl_context ssl;
    mbedtls_ssl_config cfg;
    mbedtls_net_context net;
    mbedtls_ctr_drbg_context ctr_drbg;
} tts_tls_ctx_t;

/* ── Entropy ─────────────────────────────────────────────────── */

static int tts_entropy_func(void* data, unsigned char* output, size_t len)
{
    (void)data;
    if (agent_secure_random(output, len) == 0) {
        return 0;
    }
    syslog(LOG_ERR, "[volc_tts] CRITICAL: No secure entropy source available\n");
    return -1;  /* Generic error - TLS handshake will fail safely */
}

/* ── DNS 兜底（2026-08-12，同 volc_asr）：板端解析 openspeech.bytedance.com
 * 失败（-0x52 UNKNOWN_HOST，CNAME 链），回退直连 CDN IP，SNI 不受影响 */
static const char* const s_tts_ip_fallback[] = {
    "183.240.127.14", "120.233.0.88", "183.240.127.16",
    "120.233.0.89",   "120.233.0.90", "183.240.127.15",
    NULL
};

static int tts_net_connect_fallback(tts_tls_ctx_t* ctx,
    const char* host, const char* port)
{
    int ret = mbedtls_net_connect(&ctx->net, host, port,
        MBEDTLS_NET_PROTO_TCP);

    if (ret != MBEDTLS_ERR_NET_UNKNOWN_HOST) {
        return ret;
    }

    syslog(LOG_WARNING, "[volc_tts_ws] DNS fail %s, try IP fallback\n", host);

    for (int i = 0; s_tts_ip_fallback[i]; i++) {
        ret = mbedtls_net_connect(&ctx->net, s_tts_ip_fallback[i], port,
            MBEDTLS_NET_PROTO_TCP);
        if (ret == 0) {
            syslog(LOG_INFO, "[volc_tts_ws] IP fallback connected: %s\n",
                s_tts_ip_fallback[i]);
            return 0;
        }
    }

    return ret;
}

/* ── TLS connect / free ──────────────────────────────────────── */

static void tts_tls_free(tts_tls_ctx_t* ctx);

static int tts_tls_connect(tts_tls_ctx_t* ctx, const char* host,
    const char* port)
{
    int ret;

    mbedtls_ssl_init(&ctx->ssl);
    mbedtls_ssl_config_init(&ctx->cfg);
    mbedtls_net_init(&ctx->net);
    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);

    ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, tts_entropy_func, NULL,
        (const unsigned char*)"volc_tts_ws", 11);
    if (ret != 0) {
        goto fail;
    }

    if (http_proxy_is_enabled()) {
        int tunnel_fd = proxy_open_tunnel(host, atoi(port), 30000);

        if (tunnel_fd < 0) {
            ret = -ECONNREFUSED;
            goto fail;
        }

        ctx->net.fd = tunnel_fd;
    } else {
        /* 2026-08-12：同 ASR——板端 DNS 解析失败回退直连 CDN IP */
        ret = tts_net_connect_fallback(ctx, host, port);
        if (ret != 0) {
            ret = -ECONNREFUSED;
            goto fail;
        }
    }

    mbedtls_net_set_block(&ctx->net);

    if (ctx->net.fd >= 0) {
        struct timeval tv = { .tv_sec = 10, .tv_usec = 0 };

        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    }

    ret = mbedtls_ssl_config_defaults(&ctx->cfg, MBEDTLS_SSL_IS_CLIENT,
        MBEDTLS_SSL_TRANSPORT_STREAM,
        MBEDTLS_SSL_PRESET_DEFAULT);
    if (ret != 0) {
        ret = -EIO;
        goto fail;
    }

    mbedtls_ssl_conf_min_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_3);
#else
    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
#endif

    mbedtls_ssl_conf_authmode(&ctx->cfg, MBEDTLS_SSL_VERIFY_OPTIONAL);
    mbedtls_ssl_conf_rng(&ctx->cfg, mbedtls_ctr_drbg_random, &ctx->ctr_drbg);

    ret = mbedtls_ssl_setup(&ctx->ssl, &ctx->cfg);
    if (ret != 0) {
        ret = -EIO;
        goto fail;
    }

    mbedtls_ssl_set_hostname(&ctx->ssl, host);
    mbedtls_ssl_set_bio(&ctx->ssl, &ctx->net, mbedtls_net_send, mbedtls_net_recv,
        NULL);

    syslog(LOG_INFO, "[%s] Handshake start: %s:%s\n", TAG, host, port);

    while ((ret = mbedtls_ssl_handshake(&ctx->ssl)) != 0) {
        if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
            syslog(LOG_ERR, "[%s] handshake: -0x%04x\n", TAG, -ret);
            ret = -EIO;
            goto fail;
        }
    }

    syslog(LOG_INFO, "[%s] TLS connected\n", TAG);
    return 0;

fail:
    tts_tls_free(ctx);
    return ret;
}

static void tts_tls_free(tts_tls_ctx_t* ctx)
{
    mbedtls_ssl_close_notify(&ctx->ssl);
    mbedtls_net_free(&ctx->net);
    mbedtls_ssl_free(&ctx->ssl);
    mbedtls_ssl_config_free(&ctx->cfg);
    mbedtls_ctr_drbg_free(&ctx->ctr_drbg);
}

/* ── TLS I/O helpers ─────────────────────────────────────────── */

static int tls_write_all(tts_tls_ctx_t* ctx, const unsigned char* buf,
    size_t len)
{
    size_t written = 0;

    while (written < len) {
        int ret = mbedtls_ssl_write(&ctx->ssl, buf + written, len - written);

        if (ret > 0) {
            written += (size_t)ret;
        } else if (ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
            return -EIO;
        }
    }

    return 0;
}

static int tls_read_all(tts_tls_ctx_t* ctx, unsigned char* buf, size_t len)
{
    size_t got = 0;

    while (got < len) {
        int ret = mbedtls_ssl_read(&ctx->ssl, buf + got, len - got);

        if (ret > 0) {
            got += (size_t)ret;
        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
            return -ECONNRESET;
        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
            /* Distinguish SO_RCVTIMEO timeout from real I/O errors.
             * When the socket recv timeout fires, recv() returns -1
             * with errno EAGAIN/EWOULDBLOCK, and mbedtls maps that
             * to MBEDTLS_ERR_NET_RECV_FAILED (-0x004C).  Return a
             * distinct code so callers can treat timeout as normal
             * end-of-stream without masking real connection failures. */
            if (ret == -0x004C && (errno == EAGAIN || errno == EWOULDBLOCK
                                   || errno == ETIMEDOUT)) {
                return -ETIMEDOUT;
            }
            return -EIO;
        }
    }

    return 0;
}

/* ── WebSocket upgrade (V3 auth: X-Api-Key + X-Api-Resource-Id) ─ */

static int ws_upgrade(tts_tls_ctx_t* ctx, const char* host, const char* path,
    const char* api_key, const char* resource_id)
{
    unsigned char key_raw[16];
    unsigned char key_b64[32];
    size_t key_b64_len;

    tts_entropy_func(NULL, key_raw, sizeof(key_raw));
    mbedtls_base64_encode(key_b64, sizeof(key_b64), &key_b64_len, key_raw,
        sizeof(key_raw));

    char req[896];
    int n = snprintf(req, sizeof(req),
        "GET %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Upgrade: websocket\r\n"
        "Connection: Upgrade\r\n"
        "Sec-WebSocket-Key: %.*s\r\n"
        "Sec-WebSocket-Version: 13\r\n"
        "X-Api-Key: %s\r\n"
        "X-Api-Resource-Id: %s\r\n"
        "\r\n",
        path, host, (int)key_b64_len, key_b64, api_key, resource_id);

    if (n <= 0 || n >= (int)sizeof(req)) {
        return -EOVERFLOW;
    }

    int ret = tls_write_all(ctx, (const unsigned char*)req, (size_t)n);

    if (ret != 0) {
        return ret;
    }

    char resp[1024];
    size_t rlen = 0;

    while (rlen < sizeof(resp) - 1) {
        int r = mbedtls_ssl_read(&ctx->ssl, (unsigned char*)resp + rlen,
            sizeof(resp) - 1 - rlen);

        if (r > 0) {
            rlen += (size_t)r;
            resp[rlen] = '\0';
            if (strstr(resp, "\r\n\r\n")) {
                break;
            }
        } else if (r == 0 || r == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
            return -ECONNRESET;
        } else if (r != MBEDTLS_ERR_SSL_WANT_READ) {
            return -EIO;
        }
    }

    int status = 0;

    if (sscanf(resp, "HTTP/1.1 %d", &status) != 1 || status != 101) {
        syslog(LOG_ERR, "[%s] WS upgrade failed: HTTP %d (%.200s)\n",
            TAG, status, resp);
        return -EPROTO;
    }

    syslog(LOG_INFO, "[%s] WebSocket upgrade OK\n", TAG);
    return 0;
}

/* ── WebSocket frame send (client must mask) ─────────────────── */

static int ws_send_binary(tts_tls_ctx_t* ctx, const unsigned char* payload,
    size_t plen)
{
    unsigned char hdr[14];
    size_t hdr_len = 0;

    hdr[0] = WS_FIN_BIT | WS_OPCODE_BINARY;

    if (plen < 126) {
        hdr[1] = WS_MASK_BIT | (unsigned char)plen;
        hdr_len = 2;
    } else if (plen <= 0xFFFF) {
        hdr[1] = WS_MASK_BIT | 126;
        hdr[2] = (unsigned char)(plen >> 8);
        hdr[3] = (unsigned char)(plen & 0xFF);
        hdr_len = 4;
    } else {
        hdr[1] = WS_MASK_BIT | 127;
        for (int i = 0; i < 8; i++) {
            hdr[2 + i] = (unsigned char)((plen >> (56 - 8 * i)) & 0xFF);
        }
        hdr_len = 10;
    }

    unsigned char mask[WS_MASK_KEY_LEN];

    tts_entropy_func(NULL, mask, sizeof(mask));

    int ret = tls_write_all(ctx, hdr, hdr_len);

    if (ret != 0) {
        return ret;
    }

    ret = tls_write_all(ctx, mask, sizeof(mask));
    if (ret != 0) {
        return ret;
    }

    unsigned char* masked = malloc(plen ? plen : 1);

    if (!masked) {
        return -ENOMEM;
    }

    for (size_t i = 0; i < plen; i++) {
        masked[i] = payload[i] ^ mask[i % WS_MASK_KEY_LEN];
    }

    ret = tls_write_all(ctx, masked, plen);
    free(masked);
    return ret;
}

static int ws_recv_frame(tts_tls_ctx_t* ctx, unsigned char* buf, size_t cap,
    size_t* out_len, int* out_opcode)
{
    unsigned char hdr[2];
    int ret = tls_read_all(ctx, hdr, 2);

    if (ret != 0) {
        return ret;
    }

    *out_opcode = hdr[0] & 0x0F;
    int masked = (hdr[1] & WS_MASK_BIT) != 0;
    size_t plen = hdr[1] & 0x7F;

    if (plen == 126) {
        unsigned char ext[2];

        ret = tls_read_all(ctx, ext, 2);
        if (ret != 0) {
            return ret;
        }

        plen = ((size_t)ext[0] << 8) | ext[1];
    } else if (plen == 127) {
        unsigned char ext[8];

        ret = tls_read_all(ctx, ext, 8);
        if (ret != 0) {
            return ret;
        }

        plen = ((size_t)ext[4] << 24) | ((size_t)ext[5] << 16) | ((size_t)ext[6] << 8) | ext[7];
    }

    unsigned char mask_key[WS_MASK_KEY_LEN];

    if (masked) {
        ret = tls_read_all(ctx, mask_key, WS_MASK_KEY_LEN);
        if (ret != 0) {
            return ret;
        }
    }

    if (plen > cap) {
        syslog(LOG_ERR, "[%s] WS frame too large: %zu\n", TAG, plen);
        return -EOVERFLOW;
    }

    if (plen > 0) {
        ret = tls_read_all(ctx, buf, plen);
        if (ret != 0) {
            return ret;
        }

        if (masked) {
            for (size_t i = 0; i < plen; i++) {
                buf[i] ^= mask_key[i % 4];
            }
        }
    }

    *out_len = plen;
    return 0;
}

/* ── Big-endian helpers ──────────────────────────────────────── */

static void be32(unsigned char* out, uint32_t v)
{
    out[0] = (unsigned char)((v >> 24) & 0xFF);
    out[1] = (unsigned char)((v >> 16) & 0xFF);
    out[2] = (unsigned char)((v >> 8) & 0xFF);
    out[3] = (unsigned char)(v & 0xFF);
}

static uint32_t get_be32(const unsigned char* p)
{
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16)
        | ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

static int32_t get_be32s(const unsigned char* p)
{
    return (int32_t)get_be32(p);
}

/* ── Volcengine V3 bidirectional frame send ────────────────────
 * Client send layout (marshal order): 4B header + event(i32 BE)
 * [+ session_id(u32 len + utf8)] [+ sequence(i32 BE)] + payload(u32 len + data)
 * session_id is omitted for connection-level events (Start/FinishConnection).
 * frame bytes are built in heap to avoid big stack arrays. */

static int send_volc_frame(tts_tls_ctx_t* ctx, unsigned char msg_type,
    unsigned char flags, int event, const char* session_id,
    const unsigned char* payload, size_t plen)
{
    size_t sid_len = session_id ? strlen(session_id) : 0;
    int has_event = (flags & VOLC_FLAG_WITH_EVENT) != 0;
    int has_seq = (flags == VOLC_FLAG_POS_SEQ || flags == VOLC_FLAG_NEG_SEQ);

    /* size = 4B hdr + [event 4B] + [sid len 4B + sid] + [seq 4B] + [plen 4B + payload] */
    size_t frame_len = VOLC_HDR_SIZE + 4 /* payload size field */ + plen;

    if (has_event) {
        frame_len += 4; /* event */
        /* connection-level events carry no session_id */
        if (!(event == VOLC_EVT_START_CONNECTION
                || event == VOLC_EVT_FINISH_CONNECTION)) {
            frame_len += 4 + sid_len;
        }
    }
    if (has_seq) {
        frame_len += 4;
    }

    unsigned char* frame = malloc(frame_len);

    if (!frame) {
        return -ENOMEM;
    }

    size_t off = 0;

    /* 4-byte header */
    frame[off++] = VOLC_PROTO_VER;
    frame[off++] = (unsigned char)((msg_type << 4) | flags);
    frame[off++] = (unsigned char)((VOLC_SER_JSON << 4) | 0);
    frame[off++] = 0x00;

    if (has_event) {
        be32(frame + off, (uint32_t)event);
        off += 4;
        if (!(event == VOLC_EVT_START_CONNECTION
                || event == VOLC_EVT_FINISH_CONNECTION)) {
            be32(frame + off, (uint32_t)sid_len);
            off += 4;
            if (sid_len > 0) {
                memcpy(frame + off, session_id, sid_len);
                off += sid_len;
            }
        }
    }

    if (has_seq) {
        be32(frame + off, 0); /* sequence 0 for client requests */
        off += 4;
    }

    be32(frame + off, (uint32_t)plen);
    off += 4;
    if (plen > 0) {
        memcpy(frame + off, payload, plen);
        off += plen;
    }

    int ret = ws_send_binary(ctx, frame, off);
    free(frame);
    return ret;
}

/* ── Session id generation ───────────────────────────────────── */

static void gen_session_id(char* out, size_t cap)
{
    static uint32_t s_counter = 0;
    uint32_t c = ++s_counter;

    snprintf(out, cap, "sid-%08lx-%04x",
        (unsigned long)time(NULL) & 0xFFFFFFFFUL, (unsigned)c);
}

/* ── Build and send connection/session/task events ───────────── */

static int send_start_connection(tts_tls_ctx_t* ctx)
{
    return send_volc_frame(ctx, VOLC_MSG_FULL_REQ, VOLC_FLAG_WITH_EVENT,
        VOLC_EVT_START_CONNECTION, NULL,
        (const unsigned char*)"{}", 2);
}

static int send_start_session(tts_tls_ctx_t* ctx, const char* session_id)
{
    cJSON* root = cJSON_CreateObject();

    if (!root) {
        return -ENOMEM;
    }

    /* req_params: model / speaker / audio_params (format=pcm, rate) */
    cJSON* req = cJSON_AddObjectToObject(root, "req_params");

    cJSON_AddStringToObject(req, "speaker", s_speaker);
    cJSON_AddNumberToObject(req, "sample_rate", AGENT_TTS_WS_SAMPLE_RATE);

    cJSON* audio = cJSON_AddObjectToObject(root, "audio_params");

    cJSON_AddStringToObject(audio, "format", "pcm");
    cJSON_AddNumberToObject(audio, "sample_rate", AGENT_TTS_WS_SAMPLE_RATE);

    char* json_str = cJSON_PrintUnformatted(root);

    cJSON_Delete(root);

    if (!json_str) {
        return -ENOMEM;
    }

    syslog(LOG_INFO, "[%s] StartSession sid=%s payload=%.120s\n",
        TAG, session_id, json_str);

    int ret = send_volc_frame(ctx, VOLC_MSG_FULL_REQ, VOLC_FLAG_WITH_EVENT,
        VOLC_EVT_START_SESSION, session_id,
        (const unsigned char*)json_str, strlen(json_str));
    free(json_str);
    return ret;
}

static int send_task_request(tts_tls_ctx_t* ctx, const char* session_id,
    const char* text)
{
    cJSON* root = cJSON_CreateObject();

    if (!root) {
        return -ENOMEM;
    }

    cJSON_AddStringToObject(root, "text", text);

    char* json_str = cJSON_PrintUnformatted(root);

    cJSON_Delete(root);

    if (!json_str) {
        return -ENOMEM;
    }

    syslog(LOG_INFO, "[%s] TaskRequest text=%zu bytes\n", TAG, strlen(text));

    int ret = send_volc_frame(ctx, VOLC_MSG_FULL_REQ, VOLC_FLAG_WITH_EVENT,
        VOLC_EVT_TASK_REQUEST, session_id,
        (const unsigned char*)json_str, strlen(json_str));
    free(json_str);
    return ret;
}

static int send_finish_session(tts_tls_ctx_t* ctx, const char* session_id)
{
    return send_volc_frame(ctx, VOLC_MSG_FULL_REQ, VOLC_FLAG_WITH_EVENT,
        VOLC_EVT_FINISH_SESSION, session_id,
        (const unsigned char*)"{}", 2);
}

static int send_finish_connection(tts_tls_ctx_t* ctx)
{
    return send_volc_frame(ctx, VOLC_MSG_FULL_REQ, VOLC_FLAG_WITH_EVENT,
        VOLC_EVT_FINISH_CONNECTION, NULL,
        (const unsigned char*)"{}", 2);
}

/* ── Receive and dispatch bidirectional responses ──────────────
 * Server resp layout (unmarshal order): 4B hdr + [sequence i32 BE if
 * Pos/NegSeq] + [event i32 BE] [+ session_id u32 len+utf8 if not
 * connection-level] [+ connect_id if ConnectionStarted/Failed/Finished]
 * + [payload u32 len + data].
 * Audio frames come as AudioOnlyServer (0xB) with TTSResponse (352)
 * event; the payload is raw PCM. */

static int recv_bidir_resp(tts_tls_ctx_t* ctx, volc_tts_chunk_cb cb,
    void* user_data, int* out_audio_chunks)
{
    unsigned char* buf = malloc(WS_BUF_SIZE);

    if (!buf) {
        return -ENOMEM;
    }

    int chunks = 0;
    int done = 0;
    int err = 0;
    int session_started = 0;

    while (!done) {
        size_t flen;
        int opcode;
        int ret = ws_recv_frame(ctx, buf, WS_BUF_SIZE, &flen, &opcode);

        if (ret != 0) {
            if (chunks > 0 && ret == -ETIMEDOUT) {
                /* audio already flowing; timeout = plausible end */
                break;
            }
            err = ret;
            break;
        }

        if (opcode == WS_OPCODE_CLOSE) {
            syslog(LOG_INFO, "[%s] server closed WS\n", TAG);
            break;
        }

        /* RFC6455 控制帧：ping→pong、pong/text→跳过 */
        if (opcode == 0x9) { /* ping */
            unsigned char pong[6];
            size_t pl = (flen <= 125) ? flen : 0;

            pong[0] = 0x8A; /* FIN + PONG */
            pong[1] = 0x80 | (unsigned char)pl;
            pong[2] = 0x12; pong[3] = 0x34; pong[4] = 0x56; pong[5] = 0x78;
            tls_write_all(ctx, pong, 6);
            if (pl > 0) {
                for (size_t i = 0; i < pl; i++) {
                    buf[i] ^= pong[2 + (i % 4)];
                }
                tls_write_all(ctx, buf, pl);
            }
            continue;
        }
        if (opcode == 0xA || opcode == 0x1) { /* pong / text 帧：跳过 */
            continue;
        }

        if (flen < VOLC_HDR_SIZE) {
            continue;
        }

        unsigned char msg_type = buf[1] >> 4;
        unsigned char flags = buf[1] & 0x0F;
        size_t off = VOLC_HDR_SIZE;

        /* server response: sequence precedes event (unmarshal order) */
        if (flags == VOLC_FLAG_POS_SEQ || flags == VOLC_FLAG_NEG_SEQ) {
            if (flen < off + 4) {
                continue;
            }
            off += 4; /* sequence */
        }

        int event = -1;

        if (flags & VOLC_FLAG_WITH_EVENT) {
            if (flen < off + 4) {
                continue;
            }
            event = (int)get_be32s(buf + off);
            off += 4;

            /* session_id (skip for connection-level events) */
            if (!(event == VOLC_EVT_CONNECTION_STARTED
                    || event == VOLC_EVT_CONNECTION_FAILED
                    || event == VOLC_EVT_CONNECTION_FINISHED)) {
                if (flen < off + 4) {
                    continue;
                }
                uint32_t sid_len = get_be32(buf + off);
                off += 4;
                if (sid_len > 0) {
                    if (flen < off + sid_len) {
                        continue;
                    }
                    off += sid_len;
                }
            } else {
                /* connect_id */
                if (flen < off + 4) {
                    continue;
                }
                uint32_t cid_len = get_be32(buf + off);
                off += 4;
                if (cid_len > 0) {
                    if (flen < off + cid_len) {
                        continue;
                    }
                    off += cid_len;
                }
            }
        }

        if (flen < off + 4) {
            continue;
        }

        uint32_t payload_len = get_be32(buf + off);
        off += 4;

        if (off + payload_len > flen) {
            syslog(LOG_ERR,
                "[%s] payload overrun: off=%zu plen=%lu flen=%zu\n",
                TAG, off, (unsigned long)payload_len, flen);
            continue;
        }

        const unsigned char* payload = buf + off;
        size_t plen = payload_len;

        switch (msg_type) {
        case VOLC_MSG_ERROR:
            syslog(LOG_ERR, "[%s] server error event=%d payload=%.256s\n",
                TAG, event, (char*)payload);
            err = -EIO;
            done = 1;
            break;

        case VOLC_MSG_FULL_RESP:
            if (event == VOLC_EVT_SESSION_STARTED) {
                session_started = 1;
                syslog(LOG_INFO, "[%s] SessionStarted\n", TAG);
            } else if (event == VOLC_EVT_SESSION_FINISHED
                    || event == VOLC_EVT_SESSION_FAILED
                    || event == VOLC_EVT_CONNECTION_FINISHED) {
                syslog(LOG_INFO, "[%s] session/connection finished "
                    "(event=%d)\n", TAG, event);
                done = 1;
            } else if (event == VOLC_EVT_CONNECTION_STARTED) {
                syslog(LOG_INFO, "[%s] ConnectionStarted\n", TAG);
            } else if (event == VOLC_EVT_TTS_SENTENCE_START) {
                syslog(LOG_DEBUG, "[%s] TTSSentenceStart\n", TAG);
            } else if (event == VOLC_EVT_TTS_SENTENCE_END
                    || event == VOLC_EVT_TTS_ENDED) {
                syslog(LOG_INFO, "[%s] TTS sentence end (event=%d)\n",
                    TAG, event);
                /* keep receiving until SessionFinished */
            } else if (payload_len > 0) {
                /* informational JSON (e.g. subtitle) */
                syslog(LOG_DEBUG, "[%s] full resp event=%d payload=%.120s\n",
                    TAG, event, (char*)payload);
            }
            break;

        case VOLC_MSG_AUDIO_RESP:
            /* audio-only server response — payload is raw PCM */
            if (plen > 0) {
                cb(payload, plen, 0, user_data);
                chunks++;
            }
            /* tighten recv timeout after first audio chunk */
            if (chunks == 1 && ctx->net.fd >= 0) {
                struct timeval tv = { .tv_sec = 0, .tv_usec = 500000 };
                if (setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO,
                        &tv, sizeof(tv)) < 0) {
                    syslog(LOG_WARNING,
                        "[%s] setsockopt SO_RCVTIMEO failed: %d\n",
                        TAG, errno);
                }
            }
            break;

        default:
            syslog(LOG_DEBUG, "[%s] unknown msg_type=0x%x event=%d "
                "plen=%lu\n", TAG, msg_type, event,
                (unsigned long)payload_len);
            break;
        }
    }

    free(buf);

    if (out_audio_chunks) {
        *out_audio_chunks = chunks;
    }

    if (chunks > 0 && err == 0) {
        cb(NULL, 0, 1, user_data);
    }

    syslog(LOG_INFO, "[%s] %d audio chunks delivered (err=%d)\n",
        TAG, chunks, err);

    if (chunks == 0 && err == 0) {
        return -EPROTO;
    }

    return err;
}

/* ── Init credentials ────────────────────────────────────────── */

static void tts_ws_init(void)
{
    memset(s_api_key, 0, sizeof(s_api_key));
    memset(s_resource_id, 0, sizeof(s_resource_id));
    memset(s_speaker, 0, sizeof(s_speaker));

    /* X-Api-Key: 优先 config_store（set_volc_key），回退编译期 secrets */
    if (claw_config_get(AGENT_CFG_KEY_VOLC_API_KEY,
            s_api_key, sizeof(s_api_key))
            != OK
        || s_api_key[0] == '\0') {
        strncpy(s_api_key, AGENT_SECRET_VOLC_API_KEY, sizeof(s_api_key) - 1);
    }

    /* X-Api-Resource-Id: 新版双向流式 = seed-tts-2.0（豆包语音合成大模型2.0） */
    strncpy(s_resource_id, AGENT_DOUBAO_TTS_RESOURCE,
        sizeof(s_resource_id) - 1);

    if (claw_config_get(AGENT_CFG_KEY_VOLC_SPEAKER, s_speaker,
            sizeof(s_speaker))
            != OK
        || s_speaker[0] == '\0') {
        strncpy(s_speaker, AGENT_VOICE_DEFAULT_SPEAKER,
            sizeof(s_speaker) - 1);
    }
}

/* ── Public API ──────────────────────────────────────────────── */

int volc_tts_ws_synthesize_stream(const char* text, volc_tts_chunk_cb cb,
    void* user_data)
{
    if (!text || !cb) {
        return -EINVAL;
    }

    tts_ws_init();

    if (s_api_key[0] == '\0') {
        syslog(LOG_ERR, "[%s] API key not configured\n", TAG);
        return -ENOENT;
    }

    tts_tls_ctx_t ctx;
    int ret = tts_tls_connect(&ctx, AGENT_DOUBAO_TTS_HOST, AGENT_DOUBAO_TTS_PORT);

    if (ret != 0) {
        tts_tls_free(&ctx);
        return ret;
    }

    ret = ws_upgrade(&ctx, AGENT_DOUBAO_TTS_HOST, TTS_WS_PATH,
        s_api_key, s_resource_id);
    if (ret != 0) {
        tts_tls_free(&ctx);
        return ret;
    }

    /* 1. StartConnection */
    ret = send_start_connection(&ctx);
    if (ret != 0) {
        syslog(LOG_ERR, "[%s] StartConnection failed: %d\n", TAG, ret);
        tts_tls_free(&ctx);
        return ret;
    }

    /* 2. StartSession (with generated session id) */
    char session_id[40];

    gen_session_id(session_id, sizeof(session_id));

    ret = send_start_session(&ctx, session_id);
    if (ret != 0) {
        syslog(LOG_ERR, "[%s] StartSession failed: %d\n", TAG, ret);
        tts_tls_free(&ctx);
        return ret;
    }

    /* 3. TaskRequest — synthesize this text */
    ret = send_task_request(&ctx, session_id, text);
    if (ret != 0) {
        syslog(LOG_ERR, "[%s] TaskRequest failed: %d\n", TAG, ret);
        tts_tls_free(&ctx);
        return ret;
    }

    /* 4. Receive audio frames until session finishes */
    int chunks = 0;

    ret = recv_bidir_resp(&ctx, cb, user_data, &chunks);

    /* 5. Close session + connection (best-effort) */
    send_finish_session(&ctx, session_id);
    send_finish_connection(&ctx);

    tts_tls_free(&ctx);
    return ret;
}

