/* ── Wait for a specific server event ──────────────────────────
 * 2026-08-14：官方流程要求每步等待确认（StartConnection →
 * ConnectionStarted → StartSession → SessionStarted → TaskRequest）。
 * 原实现连发三事件不等确认，且不发 FinishSession 就拿不到
 * SessionFinished（本地实测：TaskRequest 后须立即 FinishSession，
 * 服务器才回音频 + SessionFinished）。循环收帧直到 want_event，
 * 期间处理 ping/pong、跳过无关帧；Error 帧立即失败。 */

static int recv_wait_event(tts_tls_ctx_t* ctx, int want_event)
{
    unsigned char* buf = malloc(WS_BUF_SIZE);

    if (!buf) {
        return -ENOMEM;
    }

    int err = 0;

    while (1) {
        size_t flen;
        int opcode;
        int ret = ws_recv_frame(ctx, buf, WS_BUF_SIZE, &flen, &opcode);

        if (ret != 0) {
            err = ret;
            break;
        }

        if (opcode == WS_OPCODE_CLOSE) {
            syslog(LOG_ERR, "[%s] server closed while waiting "
                "event %d\n", TAG, want_event);
            err = -ECONNRESET;
            break;
        }

        /* RFC6455 控制帧：ping→pong、pong/text→跳过 */
        if (opcode == 0x9) { /* ping */
            unsigned char pong[6];
            size_t pl = (flen <= 125) ? flen : 0;

            pong[0] = 0x8A;
            pong[1] = 0x80 | (unsigned char)pl;
            pong[2] = 0x12; pong[3] = 0x34; pong[4] = 0x56; pong[5] = 0x78;
            tls_write_all(ctx, pong, 6);
            if (pl > 0) {
                for (size_t i = 0; i < pl; i++) {
                    buf[i] ^= pong[2 + (i % 4)];
                }
                tls_write_all(ctx, buf, pl);
            }
            continue;
        }
        if (opcode == 0xA || opcode == 0x1) { /* pong / text 帧：跳过 */
            continue;
        }

        size_t volc_hdr_len = (size_t)(buf[0] & 0x0F) * 4;

        if (flen < volc_hdr_len) {
            continue;
        }

        unsigned char msg_type = buf[1] >> 4;
        unsigned char flags = buf[1] & 0x0F;
        size_t off = volc_hdr_len;

        if (flags == VOLC_FLAG_POS_SEQ || flags == VOLC_FLAG_NEG_SEQ) {
            if (flen < off + 4) {
                continue;
            }
            off += 4;
        }

        int event = -1;

        if (flags & VOLC_FLAG_WITH_EVENT) {
            if (flen < off + 4) {
                continue;
            }
            event = (int)get_be32s(buf + off);
        }

        if (msg_type == VOLC_MSG_ERROR) {
            syslog(LOG_ERR, "[%s] server error while waiting "
                "event %d (got %d)\n", TAG, want_event, event);
            err = -EIO;
            break;
        }

        if (event == want_event) {
            syslog(LOG_INFO, "[%s] event %d received\n", TAG, event);
            break;
        }

        /* 无关事件（如连接级中间态）：继续等待 */
    }

    free(buf);
    return err;
}

/* ── Receive and dispatch bidirectional responses ──────────────
 * Server resp layout (unmarshal order): 4B hdr + [sequence i32 BE if
 * Pos/NegSeq] + [event i32 BE] [+ session_id u32 len+utf8 if not
 * connection-level] [+ connect_id if ConnectionStarted/Failed/Finished]
 * + [payload u32 len + data].
 * Audio frames come as AudioOnlyServer (0xB) with TTSResponse (352)
 * event; the payload is raw PCM. */

